// client/src/pages/OrderHistoryPage.tsx (excerpt)
const [sort, setSort] = useState("date_desc");
const [page, setPage] = useState(1);
// Sort dropdown: order date, total price, status (REQ-001)
// Pagination: ten orders per page, driven by the
// data-testid="pagination-next" button
async function exportCsv() {
  // Exports the filtered table to CSV via GET /api/v1/orders?export=csv
  const response = await fetch(`/api/v1/orders?sort=${sort}&page=${page}&export=csv`);
  const blob = await response.blob();
  saveBlobAs(blob, "orders.csv");
}

// server/src/api/orders.js (excerpt)
// endpoint: GET /api/v1/orders — list orders with sort (date|price|status),
// page, status filter, and a csv export
// BUG(FAIL-001): the csv export ignores the page param and streams all orders
app.get("/api/v1/orders", (req, res) => {
  const sort = req.query.sort || "date_desc";
  const page = Number(req.query.page || 1);
  const results = db.orders({ sort, page, pageSize: 10 });
  if (req.query.export === "csv") {
    return res.csv(db.ordersAll()); // ignores page — times out
  }
  res.json(results);
});

// e2e/order-history.spec.ts (excerpt)
test("Order history shows newest first and paginates", async ({ page }) => {
  await page.getByRole("link", { name: "Order history" }).click();
  const firstRow = page.getByTestId("order-table").locator("tr").first();
  expect(await firstRow.textContent()).toContain("Order #1025");
  await page.getByTestId("pagination-next").click();
});
test("Exports the filtered table to CSV", async ({ page }) => {
  const [download] = await Promise.all([
    page.waitForEvent("download"),
    page.getByRole("button", { name: "Export CSV" }).click(),
  ]);
  expect(download.suggestedFilename()).toBe("orders.csv");
});

// server/src/api/auth.js (excerpt)
const RESET_LINK_TTL_MINUTES = 30; // reset links expire after 30 minutes (REQ-002)
app.post("/api/v1/auth/reset-password", (req, res) => {
  const token = crypto.randomUUID();
  db.resetTokens.insert({
    token,
    email: req.body.email,
    expires_at: Date.now() + RESET_LINK_TTL_MINUTES * 60_000,
    used: false,
  });
  mail.sendResetLink(req.body.email, token);
  res.status(202).json({ queued: true });
});

